/* Documentation-only interactions. No API requests, credentials or persistence. */
const labels={overview:'Overview',flows:'Flows',editor:'Flow designer',connections:'Connections',runs:'Run inspector',credentials:'Credentials',deployments:'Environments',settings:'Settings'};
let screen='overview',mode='web',selectedNode='read',designerView='canvas';
const nodeInfo={start:['Manual trigger','Start with synthetic input','No external action'],read:['HTTP source','Read example JSON','source'],map:['Map fields','Select id and set status','Declarative mapping'],send:['HTTP target','Send mapped example data','target']};
const byId=id=>document.getElementById(id);
const badge=(text,variant='info')=>`<span class="cn-badge cn-badge--${variant}">${text}</span>`;
const head=(title,description,action='')=>`<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
const button=(label,action,primary=false)=>`<button class="cn-btn cn-btn--${primary?'primary':'secondary'}" data-action="${action}">${label}</button>`;
const table=(headers,rows)=>`<div class="cn-table-wrap"><table class="cn-table"><caption>Synthetic documentation fixture; not production data.</caption><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const sampleRun=()=>table(['Run','Flow','Status','Environment','Action'],[['<code>example-run-001</code>','Example HTTP mapping',badge('Succeeded','success'),'Development',button('Inspect run','runs')]]);
const views={
 overview:()=>head('Workspace overview','Development environment · illustrative content',button('Create flow','editor',true))+`<div class="stack"><div class="summary"><div><span class="cn-caption">Active deployments</span><strong>—</strong><span class="cn-caption">No live metrics connected</span></div><div><span class="cn-caption">Recent run status</span><strong>Example only</strong><span class="cn-caption">Use the fixture below to inspect a run</span></div></div><div><h2 class="cn-h4">Recent runs</h2>${sampleRun()}</div><div class="cn-alert cn-alert--info"><strong>Start with a development flow.</strong> Configure connections, validate a draft, then activate an immutable version. No live integrations exist in this prototype.</div></div>`,
 flows:()=>head('Flows','Drafts, published versions and deployments are distinct.',button('Create flow','editor',true))+table(['Flow','Draft','Published','Deployment','Action'],[['Example HTTP mapping',badge('Saved'),'v1 · illustrative',badge('Not activated','warning'),button('Open designer','editor')]]),
 editor:()=>head('Example HTTP mapping','Saved fixture draft · publishing does not activate production traffic.',button('Review publication','publish',true))+`<div class="tabs">${button('Validate fixture','validate')}${button('Preview sample','preview')}${button('Run history','runs')}<button class="cn-btn cn-btn--secondary" data-action="canvas" aria-pressed="${designerView==='canvas'}">Canvas</button><button class="cn-btn cn-btn--secondary" data-action="outline" aria-pressed="${designerView==='outline'}">Outline</button></div><div class="editor"><aside class="palette"><h2>Node palette</h2><span class="cn-caption">Proposed MVP catalog</span>${button('Manual','palette')}${button('HTTP','palette')}${button('Map fields','palette')}<p class="cn-caption">Choice/filter follow the first slice. SOAP and other protocols are planned.</p></aside><section class="canvas ${designerView==='canvas'?'flow-canvas':''}" aria-label="Flow ${designerView}"><ol class="flow-outline">${Object.entries(nodeInfo).map(([id,[title,description]])=>`<li><button class="node" data-node="${id}" aria-pressed="${id===selectedNode}"><strong>${title}</strong><span class="cn-caption">${description}</span></button></li>`).join('')}</ol><p class="cn-caption" style="margin-top:var(--cn-space-4)">${designerView==='canvas'?'Canvas blueprint only. Use Outline for structured keyboard inspection. Drag editing is planned.':'Outline demonstrates the keyboard alternative to a future canvas. No drag editor is implemented.'}</p></section><aside id="inspector" class="inspector" aria-label="Selected node configuration"></aside></div><div class="cn-alert cn-alert--info" style="margin-top:var(--cn-space-4)"><strong>Fixture preview only.</strong> A real test run must declare its environment and possible external effects.</div>`,
 connections:()=>head('Connections','Endpoint configurations and credential references.',button('Create connection','local',true))+table(['Connection','Protocol','Endpoint','Credential','Status'],[['Example source','<span class="cn-badge"><i class="cn-shape" data-s="circle" style="--c:var(--cn-teal)"></i>REST</span>','<code>source.example.invalid</code>','Example API key',badge('Draft')],['Example target','<span class="cn-badge"><i class="cn-shape" data-s="circle" style="--c:var(--cn-teal)"></i>REST</span>','<code>target.example.invalid</code>','Not configured',badge('Draft')]])+`<p class="cn-small" style="margin-top:var(--cn-space-4)">No endpoint is contacted. Test connection is a permission-controlled server operation in the proposed product.</p>`,
 runs:()=>head('Run inspector','Example run · pinned flow version v1 · Development',button('Review replay','replay'))+`<div class="stack"><div class="cn-cluster">${badge('Succeeded','success')}<code>example-run-001</code><span class="cn-caption">Fixture, no execution occurred</span></div><div class="detail-grid"><section class="cn-card"><h2 class="cn-h4">Node attempts</h2><ol class="timeline"><li>Manual trigger — accepted fixture</li><li>HTTP source — sample input</li><li>Map fields — sample output</li><li>HTTP target — simulated result</li></ol></section><section class="cn-card"><h2 class="cn-h4">Redacted output preview</h2><pre class="cn-code"><code>{
  "id": "example-001",
  "status": "received"
}</code></pre><p class="cn-caption">Real payloads require scoped access and retention checks.</p></section></div><div class="cn-alert cn-alert--warning"><strong>Replay can repeat external effects.</strong> In the product, this creates a new linked run after an explicit permission and safety check.</div></div>`,
 credentials:()=>head('Credentials','Metadata only. Secret values never appear in listings or exports.',button('Create credential','credential',true))+table(['Name','Type','Scope','Material','Action'],[['Example API key','API key','Development',badge('Not stored','warning'),button('Review replacement','credential')]])+`<div class="cn-alert cn-alert--info" style="margin-top:var(--cn-space-4)">The prototype accepts no secret input. The product needs write-only input, server-side encryption/key handling and audited resolution.</div>`,
 deployments:()=>head('Environment bindings','Publishing a version and activating it are separate actions.',button('Review activation','activate',true))+`<div class="stack">${table(['Environment','Flow version','Source binding','Target binding','State'],[['Development','v1 · illustrative','Example source','Missing credential',badge('Blocked','warning')],['Production','Not selected','Not configured','Not configured',badge('Not deployed')]])}<div class="cn-alert cn-alert--warning"><strong>Activation is blocked.</strong> Resolve required bindings and authorization before enabling triggers. A rollback affects future runs, not completed external effects.</div></div>`,
 settings:()=>head('Workspace settings','Proposed administration areas. No configuration is persisted.')+`<div class="stack"><section class="cn-card"><h2 class="cn-h4">Members and access</h2><p class="cn-small">Action/resource permissions, service principals and OIDC mapping belong here when implemented.</p></section><section class="cn-card"><h2 class="cn-h4">Retention and operations</h2><p class="cn-small">Run, payload and audit retention are separate policies. Worker capacity and restore evidence belong in administration.</p></section><div class="cn-alert cn-alert--info">Security controls are specifications, not functioning switches in this prototype.</div></div>`
};
function notify(text){
 const notice=byId('notice');notice.replaceChildren();
 const message=document.createElement('span');message.textContent=text;
 const dismiss=document.createElement('button');dismiss.type='button';dismiss.className='cn-btn cn-btn--ghost cn-btn--sm';dismiss.textContent='Dismiss';dismiss.setAttribute('aria-label','Dismiss prototype notification');dismiss.addEventListener('click',()=>notice.hidden=true);
 notice.append(message,dismiss);notice.hidden=false;
}
function navigation(){
 const groups=mode==='mobile'?[['Operate',['overview','runs','connections']]]:[['Operate',['overview','runs']],['Build',['flows','connections']],['Manage',['credentials','deployments','settings']]];
 byId('navigation').innerHTML=groups.map(([group,pages])=>`<div class="nav-group">${group}</div>${pages.map(id=>`<button class="nav-button" data-screen="${id}" ${screen===id||(screen==='editor'&&id==='flows')?'aria-current="page"':''}>${labels[id]}</button>`).join('')}`).join('');
}
function inspector(){if(screen!=='editor')return;const [title,description,binding]=nodeInfo[selectedNode];byId('inspector').innerHTML=`<h2>${title}</h2><p class="cn-small">${description}</p><div class="cn-field"><label class="cn-label" for="node-binding">Configuration / binding</label><input id="node-binding" class="cn-input" value="${binding}" readonly></div><div class="cn-field"><label class="cn-label" for="node-policy">Retry policy</label><select id="node-policy" class="cn-select"><option>One attempt (fixture)</option></select></div><span class="cn-caption">Stable ID: ${selectedNode}. Operation versions and environment bindings are pinned in real runs.</span>`;}
function render(focus=false){
 if(mode==='mobile'&&!['overview','runs','connections'].includes(screen)){screen='runs';notify('Mobile starts with operations and inspection. Use web or desktop for authoring and administration.');}
 byId('window').dataset.mode=mode;byId('breadcrumb').textContent='Example workspace / '+labels[screen];byId('screen').innerHTML=views[screen]();navigation();inspector();if(mode==='mobile')byId('screen').querySelectorAll('[data-action="local"]').forEach(el=>{el.disabled=true;el.title='Configure connections in the web or desktop application.';});if(focus)byId('main').focus();
 document.querySelectorAll('[data-mode]').forEach(el=>{if(el.tagName==='BUTTON')el.setAttribute('aria-pressed',String(el.dataset.mode===mode));});
}
document.addEventListener('click',event=>{
 const target=event.target.closest('button');if(!target)return;
 if(target.id==='theme'){const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';target.setAttribute('aria-pressed',String(dark));return;}
 if(target.dataset.mode){mode=target.dataset.mode;render();return;}
 if(target.dataset.screen){screen=target.dataset.screen;render(true);return;}
 if(target.dataset.node){selectedNode=target.dataset.node;render();byId('screen').querySelector(`[data-node="${selectedNode}"]`).focus();return;}
 const action=target.dataset.action;if(!action)return;
 if(action==='canvas'||action==='outline'){designerView=action;render();return;}
 if(views[action]){screen=action;render(true);return;}
 const messages={validate:'Fixture validation shown only. A real flow compiler and server validation are not implemented.',preview:'Sample preview is local and synthetic. No external request was sent.',publish:'Publication review: this is a proposal only; no version was saved or deployed.',activate:'Activation blocked: missing bindings. This prototype changes no environment.',replay:'Replay review only: a real replay needs authorization and may duplicate writes. No run was created.',credential:'Credential review only. Do not enter real secrets in documentation artifacts.',palette:'Palette selection is illustrative. Full graph editing and validation are planned.',local:'This control demonstrates placement only; no server data was created.'};notify(messages[action]||messages.local);
});
render();
